    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                eights.append((r, c))

    if len(eights) < 2:
        return result

    # Check if 8s form an L-shape
    # Two 8s in same row, two 8s in same col
    rows_with_8 = {}
    cols_with_8 = {}
    for (r, c) in eights:
        rows_with_8.setdefault(r, []).append(c)
        cols_with_8.setdefault(c, []).append(r)

    # Find corner of L-shape
    corner = None
    for r, cols in rows_with_8.items():
        if len(cols) > 1:
            for c, rows in cols_with_8.items():
                if len(rows) > 1 and (r, c) in eights:
                    # Corner of L
                    corner = (r, c)
                    break

    # If we found an L-shape, extend oppositional
    if corner:
        cr, cc = corner
        # New extension column (one left of existing 8s)
        new_col = cc - 1

        # Find start row - below the corner
        start_row = cr
        for r in range(start_row + 1, h):
            for c in range(w):
                if grid[r][c] == 8:
                    if new_col >= 0 and c != new_col:
                        # Going below
                        start_row = r
                        break
            else:
                continue
            break

        # Extend downward for 3 cells
        for i in range(3):
            nr = start_row + i
            if 0 <= nr < h:
                result[nr][new_col] = 8
            else:
                break

    return result

