def transform_final2(grid):
    """Correct transformation based on discovered pattern"""
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    color_positions = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            color_positions.setdefault(color, []).append((r, c))

    for color, positions in color_positions.items():
        if not positions:
            continue
        pos_list = positions

        if color == 0:
            target = pos_list[0][0] - pos_list[0][1]
            for r in range(h):
                for c in range(w):
                    if r - c == target:
                        result[r][c] = 0

        elif color == 5:
            target = pos_list[0][0] + pos_list[0][1]
            for r in range(h):
                for c in range(w):
                    if r + c == target:
                        result[r][c] = 5

        elif color == 1:
            # Two parallel anti-diagonals: first 2 on target, rest on target+1
            target = pos_list[0][0] + pos_list[0][1]

            # Find all positions on target and target+1, in order
            candidates = []
            for r in range(h):
                for c in range(w):
                    if r + c == target or r + c == target + 1:
                        candidates.append((r, c))
            candidates.sort()

            # First 4 candidates: first 2 on target, next 2 on target+1
            for ri in range(min(4, len(candidates))):
                r, c = candidates[ri]
                result[r][c] = 1

        elif color == 6:
            # Two parallel secondary diagonals: first 2 on target, rest on target+1
            target = pos_list[0][0] - pos_list[0][1]

            # Find all positions on target and target+1
            candidates = []
            for r in range(h):
                for c in range(w):
                    if r - c == target or r - c == target + 1:
                        candidates.append((r, c))
            candidates.sort()

            # First 2 on original, ALL remaining on target+1
            for ri in range(len(candidates)):
                r, c = candidates[ri]
                if ri < 2:
                    result[r][c] = 6
                else:
                    # Only fill if we're on the shifted diagonal
                    if r - c == target + 1:
                        result[r][c] = 6

        elif color == 8:
            for r, c in pos_list:
                for i in range(r + 1, h):
                    result[i][c] = 8

    return result

